若 Neumann 邊由節點 $i,j$ 構成，邊長為 $L_e$，且 $q_N$ 為常數，則邊界負載為

$$
F_\Gamma^{(e)}
=
\frac{q_NL_e}{2}
\begin{bmatrix}
1\\
1
\end{bmatrix}.
$$

def check_pure_neumann_compatibility(
        b, atol=1.0e-12, rtol=1.0e-12
):
    b = np.asarray(b, dtype=float)
    if b.ndim != 1 or not np.all(np.isfinite(b)):
        raise ValueError("b 必須是一維有限值列向量")
    if atol < 0.0 or rtol < 0.0:
        raise ValueError("atol 與 rtol 必須非負")

    defect = float(np.sum(b))
    limit = atol + rtol * float(np.linalg.norm(b, ord=1))
    if abs(defect) > limit:
        raise ValueError(
            "純 Neumann 右端不相容："
            f"sum(b)={defect}, tolerance={limit}"
        )
    return defect, limit

