def check_pure_neumann_compatibility(
        b, atol=1.0e-12, rtol=1.0e-12
):
    b = np.asarray(b, dtype=float)
    if b.ndim != 1 or not np.all(np.isfinite(b)):
        raise ValueError("b 必須是一維有限值列向量")
    if not np.isfinite(atol) or not np.isfinite(rtol):
        raise ValueError("atol 與 rtol 必須為有限值")
    if atol < 0.0 or rtol < 0.0:
        raise ValueError("atol 與 rtol 必須非負")

    defect = float(np.sum(b))
    b_norm1 = float(np.linalg.norm(b, ord=1))
    limit = atol + rtol * b_norm1
    if not np.isfinite(defect) or not np.isfinite(limit):
        raise ValueError("相容性診斷量非有限，拒絕繼續")
    if abs(defect) > limit:
        raise ValueError(
            "純 Neumann 右端不相容："
            f"sum(b)={defect}, tolerance={limit}"
        )
    return defect, limit

